73	export function countTasks(markdown: string): {
74	  total: number;
75	  completed: number;
76	  incomplete: number;
77	} {
78	  const tasks = extractTasksFromAst(markdown);
79	
80	  const total = tasks.length;
81	  const completed = tasks.filter((t) => t.checked).length;
82	
83	  return {
84	    total,
85	    completed,
86	    incomplete: total - completed,
87	  };
88	}
