90	export function getTaskLineNumber(markdown: string, taskIndex: number): number {
91	  const tasks = extractTasksFromAst(markdown);
92	
93	  if (taskIndex < 0 || taskIndex >= tasks.length) {
94	    return -1;
95	  }
96	
97	  return tasks[taskIndex].lineNumber;
98	}
