114	/**
115	 * Slugify a string into a URL-friendly anchor ID.
116	 */
117	export function slugify(text: string): string {
118	  return text
119	    .toLowerCase()
120	    .trim()
121	    .replace(/[^\w\s-]/g, "")
122	    .replace(/[\s_]+/g, "-")
123	    .replace(/-+/g, "-")
124	    .replace(/^-|-$/g, "");
125	}
