127	/**
128	 * Extract h1–h4 headings from markdown content for outline navigation.
129	 */
130	export function extractHeadings(markdown: string): HeadingItem[] {
131	  const tree = fromMarkdown(markdown, {
132	    extensions: [gfm()],
133	    mdastExtensions: [gfmFromMarkdown()],
134	  });
135	
136	  const headings: HeadingItem[] = [];
137	  const slugCounts = new Map<string, number>();
138	
139	  visit(tree, "heading", (node: Heading) => {
140	    if (node.depth < 1 || node.depth > 4) return;
141	
142	    const text = getNodeText(node as unknown as MdastNode);
143	    if (!text) return;
144	
145	    let slug = slugify(text);
146	    const count = slugCounts.get(slug) || 0;
147	    slugCounts.set(slug, count + 1);
148	    if (count > 0) slug = `${slug}-${count}`;
149	
150	    headings.push({ text, level: node.depth as 1 | 2 | 3 | 4, slug });
151	  });
152	
153	  return headings;
154	}
