156	interface MdastNode {
157	  value?: string;
158	  children?: MdastNode[];
159	}
160	
161	function getNodeText(node: MdastNode): string {
162	  if (node.value) return node.value;
163	  if (node.children) return node.children.map(getNodeText).join("");
164	  return "";
165	}
