35	  }
36	
37	  const theme = getThemeWithFallback(userGeneralSetting?.theme);
38	  const resolvedTheme = resolveTheme(theme);
39	  const isDarkTheme = resolvedTheme.includes("dark");
40	
41	  // Dynamically load highlight.js theme based on app theme
42	  useEffect(() => {
43	    const dynamicImportStyle = async () => {
44	      // Remove any existing highlight.js style
45	      const existingStyle = document.querySelector("style[data-hljs-theme]");
46	      if (existingStyle) {
47	        existingStyle.remove();
48	      }
49	
50	      try {
51	        const cssModule = isDarkTheme
52	          ? await import("highlight.js/styles/github-dark-dimmed.css?inline")
53	          : await import("highlight.js/styles/github.css?inline");
54	
55	        // Create and inject the style
56	        const style = document.createElement("style");
57	        style.textContent = cssModule.default;
58	        style.setAttribute("data-hljs-theme", isDarkTheme ? "dark" : "light");
59	        document.head.appendChild(style);
60	      } catch (error) {
61	        console.warn("Failed to load highlight.js theme:", error);
62	      }
63	    };
64	
